import{_ as r,C as a,o as s,c as n,j as d,a as l,E as e,a2 as i}from"./chunks/framework.DGvnA5EY.js";const p="/workbuddy-guide/assets/01-invest-chart.BPuNpHbK.png",_=JSON.parse('{"title":"第 18 章 把投资分析变成你的日常","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） > ⚠️ 本章只讲\\"怎么用 AI 辅助做研究整理\\"，不构成任何投资建议。 > 投资决策和盈亏责任永远在你自己。","frontmatter":{"title":"第 18 章 把投资分析变成你的日常"},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 18 章 把投资分析变成你的日常/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 18 章 把投资分析变成你的日常/index.md","lastUpdated":1791629861000}'),u={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 18 章 把投资分析变成你的日常/index.md"};function c(b,t,h,k,g,m){const o=a("Paywall");return s(),n("div",null,[t[0]||(t[0]=d("h1",{id:"第-18-章-把投资分析变成你的日常",tabindex:"-1"},[l("第 18 章 把投资分析变成你的日常 "),d("a",{class:"header-anchor",href:"#第-18-章-把投资分析变成你的日常","aria-label":'Permalink to "第 18 章 把投资分析变成你的日常"'},"​")],-1)),t[1]||(t[1]=d("blockquote",null,[d("p",null,"内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）")],-1)),e(o,{part:"2",variant:"banner"}),t[2]||(t[2]=i('<blockquote><p>⚠️ 本章只讲&quot;怎么用 AI 辅助做研究整理&quot;，<strong>不构成任何投资建议</strong>。 投资决策和盈亏责任永远在你自己。</p></blockquote><p>投资本身就是一件<strong>高度信息密集、强结构化、又极度依赖判断</strong>的事：读不完的财报、 理不清的行业、吵不停的多空。而整理碎片信息、拆解复杂材料、把思考过程摆到台面上， 恰好是 AI 擅长的。这一章讲清楚：在一次完整的股票/标的研究里，AI 到底能替你做掉 哪些低质量的重复劳动，把精力还给判断本身。</p><p><img src="'+p+'" alt="一只小黑站在一块写满曲线和数字的黑板前，用教鞭指给观众看" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;投资分析&quot;，与实际软件界面无关。</em></p><h2 id="一、先想清楚-ai-在投资里该干什么" tabindex="-1">一、先想清楚：AI 在投资里该干什么 <a class="header-anchor" href="#一、先想清楚-ai-在投资里该干什么" aria-label="Permalink to &quot;一、先想清楚：AI 在投资里该干什么&quot;">​</a></h2><p>多数人对&quot;AI 炒股&quot;的想象是让它预测涨跌。但从真实的高频用法看，绝大多数有价值的 提示词其实只集中在四类事上：<strong>读不完的财报帮我总结；行业太复杂帮我理逻辑； 市场吵太凶帮我把多空放进一张表；我怕自嗨帮我校找反证。</strong> 这四类都不是&quot;预测涨跌&quot;， 而是<strong>减少低质量思考的时间</strong>。AI 最合理的位置，是一个不知疲倦、不带情绪、随叫随到 的研究助理——它负责把事实底座打牢，把判断留给你。</p><p>动手前先用五问定标：</p><table tabindex="0"><thead><tr><th>问题</th><th>要说清什么</th><th>示例</th></tr></thead><tbody><tr><td>目标</td><td>这次研究支撑什么决定</td><td>判断是否把某只票纳入观察池，还是当下加减仓</td></tr><tr><td>标的</td><td>具体哪家公司/行业</td><td>天孚通信（300394），光通信/CPO 板块</td></tr><tr><td>材料</td><td>哪些是事实来源、哪些只是参考</td><td>年报、三季报、券商研报是事实；股吧观点只作情绪参考</td></tr><tr><td>深度</td><td>只要事实梳理，还是要到估值和多空推演</td><td>先做事实底座（Prompt 1–3），再上尽调级（Prompt 6）</td></tr><tr><td>验收</td><td>怎么判断结果可用</td><td>每个判断能追到数据来源，事实与观点分开标注</td></tr></tbody></table><h2 id="二、先选对-skill-金融场景的组合" tabindex="-1">二、先选对 Skill：金融场景的组合 <a class="header-anchor" href="#二、先选对-skill-金融场景的组合" aria-label="Permalink to &quot;二、先选对 Skill：金融场景的组合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill 名称</th><th>适合处理</th><th>本章怎么用</th><th>注意点</th></tr></thead><tbody><tr><td><strong>stock-advisor</strong></td><td>单只股票端到端分析</td><td>上传截图或给代码，自动跑技术面/基本面/交叉验证/排版</td><td>本章主线</td></tr><tr><td><strong>a-share-analyst</strong></td><td>A 股日常行情与选股</td><td>实时行情、技术指标、量化选股、每日报告</td><td>偏日常盯盘与批量筛选</td></tr><tr><td><strong>financial-expert</strong></td><td>金融数据查询与筛选</td><td>选股、基金筛选、财务指标、宏观/行业时序、研报检索</td><td>依赖数据源 MCP，需先配置</td></tr><tr><td><strong>peers-advisory-group</strong></td><td>多视角决策讨论</td><td>四位&quot;幕僚&quot;围绕一个议题交叉辩论</td><td>被 stock-advisor 作为决策模块调用</td></tr></tbody></table><blockquote><p>搭配思路：<strong>日常盯盘和批量选股用 <code>a-share-analyst</code> 与 <code>financial-expert</code>；要对一只 票下深功夫、出完整报告，用 <code>stock-advisor</code>；需要跳出单一视角、逼自己看反面时， 叫上 <code>peers-advisory-group</code>。</strong> Skill 以 SkillHub 实际上线为准，装前认准官方源。</p></blockquote>',11)),e(o,{part:"2"}),t[3]||(t[3]=d("p",null,[d("em",null,"—— 以上试读到此为止。第二篇共 11 章，完整版 PDF 包含全部实操内容。——")],-1))])}const x=r(u,[["render",c]]);export{_ as __pageData,x as default};
